with base as (select id, device, browser, started_at, country, substring(country, 1, 2) as country_prefix, case when browser = 'Chrome' then 1 else 0 end as is_chrome from sessions where started_at >= to_date('2023-08-30') and browser is not null) select * from (select browser, country, is_chrome from base) src pivot (avg(is_chrome) as amount, count(1) as cnt for country in ('SG', 'DE'));
